import{_ as i,C as a,o as n,c,j as t,a as o,E as d,ag as l}from"./chunks/framework.HG0H2VLS.js";const x=JSON.parse('{"title":"RecordTabs","description":"","frontmatter":{},"headers":[],"relativePath":"cc-patterns/record-tabs.md","filePath":"cc-patterns/record-tabs.md"}'),h={name:"cc-patterns/record-tabs.md"},b={id:"recordtabs",tabindex:"-1"};function p(g,e,m,u,f,w){const r=a("Badge"),s=a("ComponentDemo");return n(),c("div",null,[e[3]||(e[3]=t("hr",null,null,-1)),e[4]||(e[4]=t("h2",{id:"title-recordtabs",tabindex:"-1"},[o("title: RecordTabs "),t("a",{class:"header-anchor",href:"#title-recordtabs","aria-label":'Permalink to "title: RecordTabs"'},"​")],-1)),t("h1",b,[e[0]||(e[0]=o("RecordTabs ",-1)),d(r,{type:"info",text:"Design System"}),e[1]||(e[1]=o()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#recordtabs","aria-label":'Permalink to "RecordTabs <Badge type="info" text="Design System" />"'},"​",-1))]),e[5]||(e[5]=t("blockquote",null,[t("p",null,"Record section tabs (links) with count + optional Lookup / Add; Width Standard / Full")],-1)),d(s,{src:"/demos/src/cc/patterns/RecordTabs/RecordTabs.html"}),e[6]||(e[6]=l('<h2 id="token-gaps-decisions" tabindex="-1">Token Gaps &amp; Decisions <a class="header-anchor" href="#token-gaps-decisions" aria-label="Permalink to &quot;Token Gaps &amp; Decisions&quot;">​</a></h2><p>Draft active underline was <code>Lagoon/10</code> (no token) → <code>--ao-border-brand</code> (designer). Inactive underline was the borrowed <code>--ao-btn-primary-border</code> → transparent. Tabs are links: Details / Article steps are separate screens.</p><h2 id="show-sidebar-switch-2026-09-29-code-first-—-flag-for-figma" tabindex="-1">Show sidebar switch (2026-09-29, code-first — flag for Figma) <a class="header-anchor" href="#show-sidebar-switch-2026-09-29-code-first-—-flag-for-figma" aria-label="Permalink to &quot;Show sidebar switch (2026-09-29, code-first — flag for Figma)&quot;">​</a></h2><p>On View / Edit only, in <code>.record-tabs__actions</code> (far right): DS Toggle xxs + &quot;Show sidebar&quot; label (<code>.record-tabs__sidebar-toggle</code>, dressed as StepsTable&#39;s &quot;Show details&quot;). <code>record_tabs(sidebar=True|False)</code> sets the default — View on, Edit off. Hidden at <code>@container cs-page (max-width: 1023px)</code>. Not in the RecordTabs Figma set.</p><h2 id="active-tab-weight-designer-2026-09-29" tabindex="-1">Active tab weight (designer, 2026-09-29) <a class="header-anchor" href="#active-tab-weight-designer-2026-09-29" aria-label="Permalink to &quot;Active tab weight (designer, 2026-09-29)&quot;">​</a></h2><p><code>.record-tab--active</code> is <strong>SemiBold</strong> (<code>--ao-font-semibold</code>); the other tabs stay Medium. Flag for Figma.</p><h2 id="mobile-designer-2026-09-30" tabindex="-1">Mobile (designer, 2026-09-30) <a class="header-anchor" href="#mobile-designer-2026-09-30" aria-label="Permalink to &quot;Mobile (designer, 2026-09-30)&quot;">​</a></h2><p><code>@container cs-page (max-width: 767px)</code>: the Steps actions hide <strong>Import</strong> (<code>.record-tabs__import</code>) and make every icon + label tab action icon-only — <strong>+ Add</strong>, and <strong>Cancel</strong> (<code>x</code>) / <strong>Save</strong> (<code>check</code>) on the Import / Add step forms (32px square via <code>.record-tabs__actions .btn:has(&gt; .record-tabs__btn-label)</code>, label hidden, <code>aria-label</code> kept) — at ~390 the tabs, Import and Add ran into each other. The bar itself tightens to gap <code>--ao-spacing-3</code> and padding <code>--ao-spacing-0-5 --ao-spacing-4 0</code> (desktop <code>spacing-5</code> for both), and the gap between tabs (<code>.record-tabs__list</code>) to <code>--ao-spacing-3</code> (desktop <code>spacing-5</code>). Tab labels (<code>.record-tab</code>) step down to <code>--ao-font-fixed-2xs</code> (desktop <code>xs</code>).</p><h2 id="figma-build-2026-09-30" tabindex="-1">Figma build 2026-09-30 <a class="header-anchor" href="#figma-build-2026-09-30" aria-label="Permalink to &quot;Figma build 2026-09-30&quot;">​</a></h2><p>Set <code>3871:3246</code> now: Width × <strong>Actions (None | Steps | Form | Sidebar)</strong> × <strong>Device (Desktop | Mobile)</strong> — 14 variants (Sidebar has no Mobile: the switch is hidden ≤1023). The <code>Show Actions</code> boolean is gone; its instances moved to Actions=Steps (Steps screens), Sidebar (View on / Edit off), None (Narrow + Mobile). Steps = Import + Add (Lookup renamed, actions right padding removed); Form = Cancel (x) + Save (Tick); Sidebar reuses the StepsToolbar &quot;Show details&quot; toggle group.</p><h2 id="overflow-navigation-designer-2026-10-02" tabindex="-1">Overflow navigation (designer, 2026-10-02) <a class="header-anchor" href="#overflow-navigation-designer-2026-10-02" aria-label="Permalink to &quot;Overflow navigation (designer, 2026-10-02)&quot;">​</a></h2><p>When the tabs don&#39;t fit the bar, <code>.record-tabs__list</code> scrolls sideways instead of clipping. There&#39;s no visible scrollbar, and the cursor is <code>grab</code> only while it overflows (<code>--scrollable</code>, kept in step by a ResizeObserver). <code>RecordTabs.js</code> (auto-init, idempotent) adds:</p><ul><li><strong>Mouse drag</strong> (4px threshold). The click that ends a drag is swallowed, so a drag never opens a tab.</li><li><strong>Vertical wheel</strong> → horizontal scroll, only while it can move, so the page scrolls once it reaches an end.</li><li><strong>Keyboard focus</strong> brings the focused tab into view.</li><li>The <strong>active tab</strong> is brought into view on load and whenever it changes in place (MutationObserver).</li></ul><p>Touch uses native swipe. Loaded on Contract Analysis, the RecordTabs demo and every record screen (via <code>_generate.py</code> KIT_JS). Verified at 390px on Contract Analysis (452px of tabs in a 285px list); no change at desktop widths, where nothing overflows.</p><h2 id="variants" tabindex="-1">Variants <a class="header-anchor" href="#variants" aria-label="Permalink to &quot;Variants&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Node</th><th>Variant</th><th>Notes</th></tr></thead><tbody><tr><td><code>3861:1912</code></td><td>RecordTab State=Default</td><td></td></tr><tr><td><code>3861:1912</code></td><td>RecordTab State=Active</td><td>brand underline</td></tr><tr><td><code>3871:3246</code></td><td>RecordTabs Width=Standard</td><td>white bordered card</td></tr><tr><td><code>3871:3246</code></td><td>RecordTabs Width=Full</td><td>flat, bottom border</td></tr></tbody></table><h2 id="css-classes" tabindex="-1">CSS Classes <a class="header-anchor" href="#css-classes" aria-label="Permalink to &quot;CSS Classes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Figma</th><th>CSS</th></tr></thead><tbody><tr><td>Bar (nav)</td><td><code>.record-tabs (+ --full)</code></td></tr><tr><td>Tab list</td><td><code>.record-tabs__list</code></td></tr><tr><td>Tab (a)</td><td><code>.record-tab (+ --active, aria-current=&quot;page&quot;)</code></td></tr><tr><td>Count</td><td><code>.record-tab__count</code></td></tr><tr><td>Actions (Show Actions)</td><td><code>.record-tabs__actions → Import (secondary sm) + Add (primary sm)</code></td></tr><tr><td>— (code-first, 2026-09-30)</td><td>Form actions on Import step: <code>.record-tabs__actions → Cancel (secondary sm) + Save (primary sm, check)</code> — <code>record_tabs(form=…)</code>; not in the RecordTabs Figma set</td></tr></tbody></table><h2 id="token-mapping" tabindex="-1">Token Mapping <a class="header-anchor" href="#token-mapping" aria-label="Permalink to &quot;Token Mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Token</th></tr></thead><tbody><tr><td>bar</td><td>--ao-surface-primary, 1px --ao-border-secondary, --ao-radius-md; Full: radius-none, bottom border</td></tr><tr><td>bar padding / gap</td><td>--ao-spacing-0-5 top, --ao-spacing-5 sides / --ao-spacing-5</td></tr><tr><td>tab</td><td>padding --ao-spacing-5 0, gap --ao-spacing-2, --ao-font-fixed-xs Medium --ao-leading-sm</td></tr><tr><td>tab colour</td><td>--ao-text-contrast → active --ao-text-brand</td></tr><tr><td>underline</td><td>2px transparent → active --ao-border-brand</td></tr><tr><td>count</td><td>--ao-surface-info-soft, --ao-radius-full, 0 --ao-spacing-2, min-width --ao-spacing-6, --ao-font-fixed-xxs SemiBold --ao-text-info</td></tr><tr><td>actions</td><td>gap --ao-spacing-3, padding-right --ao-spacing-4</td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Built 2026-09-28 from the View &amp; Edit kit (section <code>3861:1902</code>, CC Light mode). The kit was componentised from a code-capture draft that re-tokenise had bound to random / borrowed tokens; the designer ruled &quot;your recommendations are the way to go&quot;, so bindings were normalised to the right semantic tokens in Figma first and this code follows the kit, not the draft.</li><li>Markup comes from <code>src/cc/templates/RecordScreen/record_markup.py</code> — the demo and the templates are generated from the same function, so they cannot drift.</li></ul><h2 id="figma" tabindex="-1">Figma <a class="header-anchor" href="#figma" aria-label="Permalink to &quot;Figma&quot;">​</a></h2><p><a href="https://www.figma.com/design/Lus07xi8pPXLN87sQIyrEt/Affino---Design-System?node-id=3871-3246" target="_blank" rel="noreferrer">Open in Figma</a></p>',24))])}const v=i(h,[["render",p]]);export{x as __pageData,v as default};
